              application++;
              assertEquals("QUESTION_RETRY_EXHAUSTED", physical.getStringProperty("NKErrorCode"));
              assertEquals(4, physical.getIntProperty("NKDeliveryCount"));
              assertEquals("API_WORK", physical.getStringProperty("NKDetectedBy"));
