          h.sql(
              "insert into schubert.answers(question_id,body,answered_at,provider_type,created_at,updated_at) values(1,'','2026-10-01T00:00:00.123456Z','STUB','2026-10-01T00:00:00.123456Z','2026-10-01T00:00:00.123456Z')");
