      for (int i = 0; i < 7; i++) {
        var args = new ArrayList<>(valid);
        args.set(i, "null");
        state(c, args, "22023");
      }
      Map<Integer, List<String>> bad =
          Map.of(
              1,
              List.of("'infinity'", "'-infinity'", "'0001-01-01 BC'"),
