                        credential(),
                        session -> {
                          var pair = session.beginBackup(run, began, false);
                          confirmActualFailedPair(session, pair);
                          assertEquals(30, session.handoffCleanup(() -> 30));
                          try {
                            before.set(mdb588Audit(observer, run));
